// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        // Drive c through DrugDealer from an arbitrary fuzzed actor.
        vm.prank(caller);
        try c.DrugDealer() {
            // If the call succeeds, the invariant demands the caller now IS the CEO:
            // DrugDealer's only effect in the reference is ceoAddress = msg.sender.
            assertTrue(c.ceoAddress() == caller, "successful DrugDealer must make caller the ceoAddress");
        } catch {
            // Reverting is always admissible for a non-CEO caller; nothing else to check.
            assertTrue(true, "revert is admissible");
        }
    }
}

