pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // current CEO initiates the role transfer
        vm.prank(c.ceoAddress());
        c.DrugDealer();
        // any address may now act as CEO: after a successful transfer,
        // DrugDealer must be callable by any address a (role actually moved)
        vm.prank(actor);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "new CEO must be able to call DrugDealer");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);

        // The current (initial) CEO hands the role to the fuzzed actor.
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        // Now the fuzzed actor is the CEO and calls DrugDealer again.
        vm.prank(actor);
        c.DrugDealer();

        // Rule: a successful DrugDealer() call by the sitting CEO sets ceoAddress() to the caller.
        assertTrue(c.ceoAddress() == actor);
    }
}

